class BaseLLMController(ABC):
    @abstractmethod
    def get_completion(
        self,
        prompt: str,
        response_format: Optional[dict] = None,
        temperature: float = 0.7,
    ) -> str:
        pass


class OpenAIController(BaseLLMController):
    def __init__(self, model: str, api_key: Optional[str] = None):
        from openai import OpenAI
        api_key = api_key or os.getenv("OPENAI_API_KEY")

        if not api_key:
            raise ValueError("Missing OpenAI API key.")

        self.model = model
        self.client = OpenAI(
            api_key=api_key,
            base_url=os.getenv("OPENAI_BASE_URL"),
        )

    def get_completion(
        self,
        prompt: str,
        response_format: Optional[dict] = None,
        temperature: float = 0.7,
    ) -> str:

        system_msg = (
            "You must respond with a JSON object that matches the schema."
            if response_format else
            "You are a helpful assistant."
        )

        # Deepseek-like models may need schema constraints appended
        if self.model.startswith("deepseek") and response_format:
            prompt = append_schema_constraints_to_prompt(prompt, response_format)  # noqa: F405

        messages = [
            {"role": "system", "content": system_msg},
            {"role": "user", "content": prompt},
        ]

        kwargs = {
            "model": self.model,
            "messages": messages,
            "temperature": temperature,
            "max_tokens": 4000,
        }

        if response_format and not self.model.startswith("deepseek"):
            kwargs["response_format"] = response_format

        resp = self.client.chat.completions.create(**kwargs)
        return resp.choices[0].message.content


class OllamaController(BaseLLMController):
    def __init__(self, model: str):
        self.model = model

    def _empty_value(self, t: str) -> Any:
        return {"array": [], "string": "", "object": {}, "number": 0, "boolean": False}.get(t, None)

    def _empty_schema_response(self, fmt: dict) -> dict:
        schema = fmt["json_schema"]["schema"]
        props = schema.get("properties", {})
        return {name: self._empty_value(p["type"]) for name, p in props.items()}

    def get_completion(
        self,
        prompt: str,
        response_format: Optional[dict] = None,
        temperature: float = 0.7,
    ) -> str:

        system_msg = (
            "You must respond with a JSON object that matches the schema."
            if response_format else
            "You are a helpful assistant."
        )
        # if "qwen3" in self.model.lower():
            # prompt+="/no_think"
            # print("-------------------Using Qwen3 model with /no_think directive.")

        try:
            if "qwen3" in self.model.lower():
                kwargs = {
                    "model": f"ollama_chat/{self.model}",
                    "messages": [
                        {"role": "system", "content": system_msg},
                        {"role": "user", "content": prompt},
                    ],
                    "temperature": temperature,
                    "think": False,
                }
            else:
                kwargs = {
                    "model": f"ollama_chat/{self.model}",
                    "messages": [
                        {"role": "system", "content": system_msg},
                        {"role": "user", "content": prompt},
                    ],
                    "temperature": temperature,
                }

            if response_format:
                kwargs["response_format"] = response_format

            resp = completion(**kwargs)
            return resp.choices[0].message.content

        except Exception:
            if response_format:
                return json.dumps(self._empty_schema_response(response_format), ensure_ascii=False)
            raise


class LLMController:
    def __init__(
        self,
        backend: Literal["openai", "ollama"],
        model: str,
        api_key: Optional[str] = None,
    ):
        if backend == "openai":
            self.llm = OpenAIController(model=model, api_key=api_key)
        elif backend == "ollama":
            self.llm = OllamaController(model=model)
        else:
            raise ValueError("Backend must be one of: openai, ollama")


# =========================
# Knowledge Graph
# =========================

class KnowledgeGraph:
    """
    G = (V, E)
    V: Entity
    E: Relation
    """
    def __init__(self):
        self.entities: Dict[str, Entity] = {}
        self.relations: Dict[str, Relation] = {}
        self.name_index: Dict[str, str] = {}
        self.out_edges: Dict[str, List[str]] = {}
        self.in_edges: Dict[str, List[str]] = {}

    def _normalize_name(self, name: str) -> str:
        return name.strip().lower()

    def _index_entity_names(self, entity: Entity):
        all_names = [entity.name]
        aliases = entity.metadata.get("aliases") or []
        if isinstance(aliases, list):
            for a in aliases:
                if isinstance(a, str) and a.strip():
                    all_names.append(a.strip())

        for n in all_names:
            key = self._normalize_name(n)
            if key and key not in self.name_index:
                self.name_index[key] = entity.id

    def add_entity(
        self,
        name: str,
        metadata: Optional[Dict[str, Any]] = None,
        entity_id: Optional[str] = None
    ) -> str:
        if metadata is None:
            metadata = {}

        eid = entity_id or str(uuid.uuid4())

        entity = Entity(
            id=eid,
            name=name,
            metadata=metadata
        )
        self.entities[eid] = entity

        self.out_edges.setdefault(eid, [])
        self.in_edges.setdefault(eid, [])
        self._index_entity_names(entity)

        return eid

    def add_entity_node(self, name: str, metadata: Optional[Dict[str, Any]] = None) -> str:
        meta = metadata or {}
        meta.setdefault("node_type", "entity")
        meta.setdefault("aliases", [])
        return self.add_entity(name=name, metadata=meta)

    def add_passage_node(self, text: str, metadata: Optional[Dict[str, Any]] = None) -> str:
        meta = metadata or {}
        meta.setdefault("node_type", "passage")

        return self.add_entity(name=text, metadata=meta)

    def add_experience_node(self, text: str, metadata: Optional[Dict[str, Any]] = None) -> str:
        meta = metadata or {}
        meta.setdefault("node_type", "experience")
        return self.add_entity(name=text, metadata=meta)

    def get_entity(self, key: str) -> Optional[Entity]:
        if key in self.entities:
            return self.entities[key]

        norm = self._normalize_name(key)
        if norm in self.name_index:
            eid = self.name_index[norm]
            return self.entities.get(eid)

        return None

    def get_or_add_entity(
        self,
        name: str,
        metadata: Optional[Dict[str, Any]] = None
    ) -> str:
        existing = self.get_entity(name)
        if existing is not None:
            # 可更新 metadata 的别名
            if metadata:
                # 合并 aliases
                if "aliases" in metadata and isinstance(metadata["aliases"], list):
                    exist_alias = existing.metadata.get("aliases") or []
                    if not isinstance(exist_alias, list):
                        exist_alias = []
                    for a in metadata["aliases"]:
                        if isinstance(a, str) and a.strip() and a not in exist_alias:
                            exist_alias.append(a)
                    existing.metadata["aliases"] = exist_alias
                    # 重新索引
                    self._index_entity_names(existing)
            return existing.id
        return self.add_entity(name=name,  metadata=metadata or {})

    def add_relation(
        self,
        source_id: str,
        target_id: str,
        relation_type: str,
        metadata: Optional[Dict[str, Any]] = None,
        relation_id: Optional[str] = None
    ) -> str:
        if metadata is None:
            metadata = {}

        if source_id not in self.entities:
            raise ValueError(f"source entity {source_id} not found")
        if target_id not in self.entities:
            raise ValueError(f"target entity {target_id} not found")

        rid = relation_id or str(uuid.uuid4())
        rel = Relation(
            id=rid,
            source=source_id,
            target=target_id,
            relation_type=relation_type,
            metadata=metadata
        )
        self.relations[rid] = rel

        self.out_edges.setdefault(source_id, []).append(rid)
        self.in_edges.setdefault(target_id, []).append(rid)

        return rid

    def get_neighbour(
        self,
        entity_id: str,
        max_hop: int = 1,
        include_passages: bool = False,
        include_experiences: bool = False,
    ) -> Dict[str, List[Any]]:

        if entity_id not in self.entities:
            return {"entities": [], "relations": []}

        visited_entities: set[str] = {entity_id}
        visited_relations: set[str] = set()

        # passages
        if include_passages:
            for rid in self.in_edges.get(entity_id, []):
                rel = self.relations.get(rid)
                if not rel or rel.relation_type != "contains":
                    continue
                src_ent = self.entities.get(rel.source)
                if src_ent and src_ent.metadata.get("node_type") == "passage":
                    visited_entities.add(src_ent.id)
                    visited_relations.add(rid)

        # experiences
        if include_experiences:
            for rid in self.in_edges.get(entity_id, []):
                rel = self.relations.get(rid)
                if not rel or rel.relation_type != "about":
                    continue
                src_ent = self.entities.get(rel.source)
                if src_ent and src_ent.metadata.get("node_type") == "experience":
                    visited_entities.add(src_ent.id)
                    visited_relations.add(rid)

        frontier: set[str] = {entity_id}
        for _ in range(max_hop):
            new_frontier: set[str] = set()
            for eid in list(frontier):
                for rid in self.out_edges.get(eid, []):
                    rel = self.relations.get(rid)
                    if not rel:
                        continue
                    if rel.relation_type in ("contains", "about", "src_of", "tgt_of", "time_of"):
                        continue

                    tgt_ent = self.entities.get(rel.target)
                    if not tgt_ent:
                        continue
                    if tgt_ent.metadata.get("node_type", "entity") != "entity":
                        continue

                    visited_relations.add(rid)
                    if tgt_ent.id not in visited_entities:
                        visited_entities.add(tgt_ent.id)
                        new_frontier.add(tgt_ent.id)

                for rid in self.in_edges.get(eid, []):
                    rel = self.relations.get(rid)
                    if not rel:
                        continue
                    if rel.relation_type in ("contains", "about", "src_of", "tgt_of", "time_of"):
                        continue

                    src_ent = self.entities.get(rel.source)
                    if not src_ent:
                        continue
                    if src_ent.metadata.get("node_type", "entity") != "entity":
                        continue

                    visited_relations.add(rid)
                    if src_ent.id not in visited_entities:
                        visited_entities.add(src_ent.id)
                        new_frontier.add(src_ent.id)

            frontier = new_frontier
            if not frontier:
                break

        entities = [self.entities[eid] for eid in visited_entities]
        relations = [self.relations[rid] for rid in visited_relations]

        return {"entities": entities, "relations": relations}

    # --- dynamic merge/update utilities ---

    def merge_entities(
        self,
        keep_eid: str,
        remove_eid: str,
        alias: Optional[str] = None
    ) -> bool:
        """
        Merge 'remove_eid' into 'keep_eid':
        - redirect all relations touching remove_eid to keep_eid
        - delete remove entity and its adjacency lists
        - add alias into keep entity metadata.aliases (optional)
        Returns True if merged successfully.
        """
        if keep_eid == remove_eid:
            return False
        if keep_eid not in self.entities or remove_eid not in self.entities:
            return False

        keep_ent = self.entities[keep_eid]
        rem_ent = self.entities[remove_eid]

        if alias and isinstance(alias, str) and alias.strip():
            aliases = keep_ent.metadata.get("aliases") or []
            if not isinstance(aliases, list):
                aliases = []
            if alias not in aliases:
                aliases.append(alias)
            keep_ent.metadata["aliases"] = aliases

        # Also add removed name as alias
        rem_name = rem_ent.name
        if rem_name and rem_name != keep_ent.name:
            aliases = keep_ent.metadata.get("aliases") or []
            if not isinstance(aliases, list):
                aliases = []
            if rem_name not in aliases:
                aliases.append(rem_name)
            keep_ent.metadata["aliases"] = aliases

        # Re-index keep entity names (and aliases)
        self._index_entity_names(keep_ent)

        # Redirect relations
        # Note: We do NOT deduplicate relations here (per user request).
        for rid, rel in list(self.relations.items()):
            changed = False
            if rel.source == remove_eid:
                rel.source = keep_eid
                changed = True
            if rel.target == remove_eid:
                rel.target = keep_eid
                changed = True
            if changed:
                # fix adjacency: remove rid from old lists, add to new
                # old adjacency might not contain due to earlier inconsistencies; safe remove
                if rid in self.out_edges.get(remove_eid, []):
                    self.out_edges[remove_eid].remove(rid)
                if rid in self.in_edges.get(remove_eid, []):
                    self.in_edges[remove_eid].remove(rid)

                self.out_edges.setdefault(rel.source, [])
                self.in_edges.setdefault(rel.target, [])
                if rid not in self.out_edges[rel.source]:
                    self.out_edges[rel.source].append(rid)
                if rid not in self.in_edges[rel.target]:
                    self.in_edges[rel.target].append(rid)

        # Delete entity
        self.entities.pop(remove_eid, None)
        self.out_edges.pop(remove_eid, None)
        self.in_edges.pop(remove_eid, None)

        # Remove from name_index any mapping pointing to removed_eid
        for k, v in list(self.name_index.items()):
            if v == remove_eid:
                self.name_index.pop(k, None)

        return True

    def dedup_relations_ignore_condition(
        self,
        keep: str = "first",          # "first" or "latest"
        include_time: bool = True,    # True: (src, type, tgt, time) / False: (src, type, tgt)
    ) -> int:
        """
        全量去重 KG.relations，忽略 condition。
        去重 key:
          - include_time=True  -> (source, relation_type, target, time)
          - include_time=False -> (source, relation_type, target)

        keep:
          - "first": 保留最先出现的 relation（遍历顺序）
          - "latest": 保留 time 更“长/非空”的那条（简单启发式；不解析时间戳）
        返回：删除的重复 relation 数量
        """

        if not self.relations:
            return 0

        def _time_of(rel) -> str:
            try:
                return str((rel.metadata or {}).get("time", "")).strip()
            except Exception:
                return ""

        # 1) 找出要保留的 relation（以及要删的）
        key_to_keep_id: Dict[Tuple, str] = {}
        to_delete: List[str] = []

        for rid, rel in list(self.relations.items()):
            t = _time_of(rel) if include_time else ""
            key = (rel.source, rel.relation_type, rel.target, t) if include_time else (rel.source, rel.relation_type, rel.target)

            if key not in key_to_keep_id:
                key_to_keep_id[key] = rid
                continue

            # 已有同 key 的 relation：决定保留谁
            keep_id = key_to_keep_id[key]
            keep_rel = self.relations.get(keep_id)

            if keep == "latest" and keep_rel is not None:
                # 启发式：优先保留 time 更“信息量大”的（非空、长度更长）
                t_keep = _time_of(keep_rel)
                t_cur = _time_of(rel)
                score_keep = (1 if t_keep else 0, len(t_keep))
                score_cur = (1 if t_cur else 0, len(t_cur))

                if score_cur > score_keep:
                    # 换保留对象：旧的标记删除
                    to_delete.append(keep_id)
                    key_to_keep_id[key] = rid
                else:
                    to_delete.append(rid)
            else:
                # 默认 keep="first"
                to_delete.append(rid)

        if not to_delete:
            return 0

        # 2) 真正删除 relation，并维护 out_edges / in_edges
        for rid in to_delete:
            rel = self.relations.pop(rid, None)
            if not rel:
                continue

            # out_edges
            outs = self.out_edges.get(rel.source)
            if outs and rid in outs:
                outs.remove(rid)

            # in_edges
            ins = self.in_edges.get(rel.target)
            if ins and rid in ins:
                ins.remove(rid)

        return len(to_delete)


